namespace RonSijm.FluidHumidifier.Factories.S3;

public class InnerBucketMetadataConfigurationFactory(Action<Humidifier.S3.BucketTypes.MetadataConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.S3.BucketTypes.MetadataConfiguration>
{

    internal InnerBucketMetadataDestinationFactory DestinationFactory { get; set; }

    internal InnerBucketJournalTableConfigurationFactory JournalTableConfigurationFactory { get; set; }

    internal InnerBucketInventoryTableConfigurationFactory InventoryTableConfigurationFactory { get; set; }

    internal InnerBucketAnnotationTableConfigurationFactory AnnotationTableConfigurationFactory { get; set; }

    protected override Humidifier.S3.BucketTypes.MetadataConfiguration Create()
    {
        var metadataConfigurationResult = CreateMetadataConfiguration();
        factoryAction?.Invoke(metadataConfigurationResult);

        return metadataConfigurationResult;
    }

    private Humidifier.S3.BucketTypes.MetadataConfiguration CreateMetadataConfiguration()
    {
        var metadataConfigurationResult = new Humidifier.S3.BucketTypes.MetadataConfiguration();

        return metadataConfigurationResult;
    }
    public override void CreateChildren(Humidifier.S3.BucketTypes.MetadataConfiguration result)
    {
        base.CreateChildren(result);

        result.Destination ??= DestinationFactory?.Build();
        result.JournalTableConfiguration ??= JournalTableConfigurationFactory?.Build();
        result.InventoryTableConfiguration ??= InventoryTableConfigurationFactory?.Build();
        result.AnnotationTableConfiguration ??= AnnotationTableConfigurationFactory?.Build();
    }

} // End Of Class

